INSERT INTO `ai_agent` VALUES (8, 'blog_outline_agent', '博客目录生成 Agent', '根据用户提供的主题，自动生成带目录结构的完整博客文章', 'blog_outline_agent', 1, '{\"type\":\"object\",\"required\":[\"topic\"],\"properties\":{\"topic\":{\"type\":\"string\",\"description\":\"博客主题\"}}}', '{\"type\":\"object\",\"properties\":{\"outline\":{\"type\":\"string\",\"description\":\"目录大纲\"},\"blogContent\":{\"type\":\"string\",\"description\":\"完整博客正文\"}}}', NULL, NULL, NULL, 1, 1, '2026-07-23 20:24:01', '2026-07-23 20:24:01');
