-- 注意只清运行记录，编排图与 Agent 定义属于配置，必须保留。
DELETE FROM `ai_agent_instance_transition`;
DELETE FROM `ai_agent_instance`;
DELETE FROM `ai_agent_iteration`;
DELETE FROM `ai_flow_run_node`;
DELETE FROM `ai_flow_run`;
DELETE FROM `ai_harness_confirmation`;
DELETE FROM `ai_harness_operation`;
DELETE FROM `ai_flow_draft`;

-- nebula.sql 里也有 blog_series 的旧版节点，且主键与此处不重叠。
-- 不先清掉会新旧并存导致流程图错乱，故本文件接管的流程整体重建。
DELETE FROM `ai_flow_edge` WHERE `flow_code` IN ('blog_series', 'daily_blog_creator', 'blog_outline_agent', 'daily_blog_generator', 'blog_generation');
DELETE FROM `ai_flow_node` WHERE `flow_code` IN ('blog_series', 'daily_blog_creator', 'blog_outline_agent', 'daily_blog_generator', 'blog_generation');
DELETE FROM `ai_flow`      WHERE `flow_code` IN ('blog_series', 'daily_blog_creator', 'blog_outline_agent', 'daily_blog_generator', 'blog_generation');

